+func semanticSQLiteTableCount(db *sql.DB, table string) (int, error) {
+	var count int
+	if err := db.QueryRow(`SELECT COUNT(*) FROM ` + table).Scan(&count); err != nil {
+		return 0, fmt.Errorf("validate semantic sqlite table %s: %w", table, err)
+	}
+	return count, nil
+}
